'use strict';
function bulkUnlockTargets(){const scope=document.getElementById('bulk-unlock-scope').value,filter=scope;if(scope==='duplicates')return KanjiCollection.duplicateUnlockTargets(gameState,getRealReadings);let items=gameState.inventory.filter(i=>filter==='all'||filter==='fish'&&KanjiFishCharacters.has(i)||filter==='element'&&KanjiElementCharacters.has(i)||filter==='special'&&!!KanjiTraits.get(i)||filter==='secret'&&isSecretKanji(i)||String(i.jis)===filter);return items.filter(i=>i.locked);}
window.bulkUnlockInventory=()=>{const items=bulkUnlockTargets();if(!items.length){document.getElementById('bulk-unlock-status').textContent='対象のロック中の文字はありません。';return;}const label=document.getElementById('bulk-unlock-scope').selectedOptions[0].textContent;if(!confirm(`${label}の${items.length}体をロック解除しますか？解除した文字は売却・錬成に使えるようになります。新しく入手する文字の自動ロック設定は維持します。`))return;const count=KanjiCollection.unlockMany(items);saveState();renderCollection();renderDeckSlots();renderSynthesisGrid();renderAutoLockSettings();document.getElementById('bulk-unlock-status').textContent=`${count}体のロックを解除しました。`;};
window.addEventListener('load',()=>{const panel=document.createElement('section');panel.className='auto-lock-panel';panel.id='bulk-unlock-panel';panel.innerHTML='<h3>まとめてロック解除</h3><label for="bulk-unlock-scope">対象 <select id="bulk-unlock-scope"><option value="duplicates">重複文字の自動ロックを解除</option><option value="1">JIS第1水準</option><option value="2">JIS第2水準</option><option value="3">JIS第3水準</option><option value="4">JIS第4水準</option><option value="element">元素文字</option><option value="fish">魚偏の文字</option><option value="special">特殊文字</option><option value="all">所持文字すべて</option></select></label><button type="button" class="inventory-action secondary" onclick="bulkUnlockInventory()">対象をロック解除</button><p>重複文字は各文字の最も育った1体・編成中・手動ロックを保護し、余分な自動ロック分だけ解除。解除は現在所持している文字に適用。新しく入手する文字は自動ロック設定に従います。</p><p id="bulk-unlock-status" role="status" aria-live="polite"></p>';document.getElementById('auto-lock-panel').before(panel);});
